#include <cmath>
#include <algorithm>
extern "C" void paint(double *P,int len,int scale,float *out) {
const double PX=.22185986964255727;
int n=1024/scale;
std::fill(out,out+n*n,0.f);
double rx=P[0]*PX,ry=P[1]*PX,th=atan2(P[4]-P[1],P[3]-P[0]),w=0,d=0;
for(int i=0;i<len;i++) {
 double x=P[3*i]*PX,y=P[3*i+1]*PX,z=P[3*i+2],zz=std::min(std::max(z,0.),15.)/10;
 double W=z>0?std::max(0.,(-.030+1.187*zz)*10):0;
 double D=z>0?std::max(0.,(.138+1.075*zz)*10):0;
 double O=z>0?std::max(0.,(1.115-.967*pow(zz-1.091,2))*10):0;
 w=.02*w+.98*W;d=.02*d+.98*D;
 double vx=x-rx,vy=y-ry,L=hypot(vx,vy);
 if(L>(z>0?1:.1))th=atan2(vy,vx);
 if(L>0){double o=std::min(O,L);rx=x-vx*o/L;ry=y-vy*o/L;}
 if(z<=0||w<.001)continue;
 double ex=cos(th),ey=sin(th),nx=-ey,ny=ex,hw=w/2;
 double xmin=std::min({rx+hw*nx,rx-hw*nx,rx-d*ex+hw*nx,rx-d*ex-hw*nx});
 double xmax=std::max({rx+hw*nx,rx-hw*nx,rx-d*ex+hw*nx,rx-d*ex-hw*nx});
 double ymin=std::min({ry+hw*ny,ry-hw*ny,ry-d*ey+hw*ny,ry-d*ey-hw*ny});
 double ymax=std::max({ry+hw*ny,ry-hw*ny,ry-d*ey+hw*ny,ry-d*ey-hw*ny});
 for(int v=std::max(0,int(ymin/(PX*scale))-1);v<std::min(n,int(ymax/(PX*scale))+2);v++) {
 for(int u=std::max(0,int(xmin/(PX*scale))-1);u<std::min(n,int(xmax/(PX*scale))+2);u++) {
 double qx=u*PX*scale-rx,qy=v*PX*scale-ry;
 double ss=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
 double fp=d*(1-4*t*t/(w*w))-ss,g=sqrt(1+pow(8*d*t/(w*w),2)),sd=std::min(ss,fp/g);
 float a=std::min(1.,std::max(0.,sd/(PX*scale)+.5));
 out[v*n+u]=std::max(out[v*n+u],a);
 }}
}
}
